 elif name in ['deadzone','deadphase']:r=p[1]*np.sign(w)*np.maximum(np.abs(w)-p[2],0)+p[3]
 elif name=='cubic':r=p[1]*w+p[2]*w**3+p[3]
 elif name=='tanh':r=p[1]*np.tanh(p[2]*w)/p[2]+p[3]
 elif name=='phase':r=p[1]*w+p[2]
